const service = global.get('inventory');
const store = global.get('inventoryStore') || service.createInitialStore();
global.set('inventoryStore', store);
const config = store.configs[service.DEFAULT_TRAY_ID];
const localConfig = { topic: `inventory/${config.id}/config/set`, payload: { schema: '1', ...config }, retain: true, qos: 1 };
const wokwiConfig = { topic: 'rack30/wokwi/a6c13d8e/config/set', payload: { schema: '1', ...config }, retain: true, qos: 1 };
return [localConfig, wokwiConfig];

const service = global.get('inventory');
const store = global.get('inventoryStore') || service.createInitialStore();
const result = service.processTelemetry(store, msg.topic, msg.payload);
global.set('inventoryStore', result.store);
const publish = (item) => item ? { ...item, qos: 1 } : null;
return [publish(result.stateMessage), publish(result.alertMessage), publish(result.restockMessage), publish(result.restockStateMessage)];

const service = global.get('inventory');
const store = global.get('inventoryStore') || service.createInitialStore();
const result = service.processConfigAck(store, msg.topic, msg.payload);
global.set('inventoryStore', result.store);
return [result.stateMessage ? { ...result.stateMessage, qos: 1 } : null, result.alertMessage ? { ...result.alertMessage, qos: 1 } : null];

const service = global.get('inventory');
const store = global.get('inventoryStore') || service.createInitialStore();
const result = service.processDeviceStatus(store, msg.topic, msg.payload);
global.set('inventoryStore', result.store);
const publish = (item) => item ? { ...item, qos: 1 } : null;
return [publish(result.stateMessage), publish(result.alertMessage)];

const service = global.get('inventory');
const store = global.get('inventoryStore') || service.createInitialStore();
const resource = msg.req.params.resource;
const trays = Object.values(store.configs).map((config) => ({ ...config, ...(store.trays[config.id] || { id: config.id, online: false, health: 'awaiting_data', isLowStock: false, actuatorLed: 'off' }) }));
const data = {
  health: { ok: true, service: 'inventory-middleware' },
  trays,
  alerts: store.alerts,
  orders: store.orders,
};
if (!Object.hasOwn(data, resource)) {
  msg.statusCode = 404;
  msg.payload = { error: 'Unknown API resource' };
} else {
  msg.statusCode = 200;
  msg.payload = data[resource];
}
msg.headers = { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' };
return msg;

const service = global.get('inventory');
const store = global.get('inventoryStore') || service.createInitialStore();
try {
  const result = service.updateTrayConfig(store, msg.req.params.trayId, msg.payload || {});
  global.set('inventoryStore', result.store);
  const configPayload = { schema: '1', ...result.config };
  const downlink = { topic: `inventory/${result.config.id}/config/set`, payload: configPayload, qos: 1, retain: true };
  const wokwiDownlink = { topic: 'rack30/wokwi/a6c13d8e/config/set', payload: configPayload, qos: 1, retain: true };
  const response = { ...msg, statusCode: 200, payload: { config: result.config, published: true }, headers: { 'content-type': 'application/json; charset=utf-8' } };
  return [downlink, wokwiDownlink, response];
} catch (error) {
  const response = { ...msg, statusCode: 400, payload: { error: error.message }, headers: { 'content-type': 'application/json; charset=utf-8' } };
  return [null, null, response];
}

const service = global.get('inventory');
const store = global.get('inventoryStore') || service.createInitialStore();
try {
  const input = msg.payload || {};
  const result = service.createSimulationPayload(store, input);
  const telemetry = input.online === false ? null : { topic: `inventory/${result.trayId}/telemetry`, payload: result.telemetry, qos: 1 };
  const status = { topic: `inventory/${result.trayId}/status`, payload: result.status, qos: 1 };
  const response = { ...msg, statusCode: 202, payload: { accepted: true, trayId: result.trayId, scenario: input.online === false ? 'device_offline' : result.telemetry.sensorValid ? 'telemetry' : 'sensor_error' }, headers: { 'content-type': 'application/json; charset=utf-8' } };
  const wokwiLoad = input.online === false ? null : { topic: 'rack30/wokwi/a6c13d8e/load', payload: { schema: '1', sensorValid: result.telemetry.sensorValid !== false, grossWeightGrams: Number(result.telemetry.grossWeightGrams || 0) }, qos: 1 };
  if (wokwiLoad) node.warn(`Wokwi MQTT publish: ${wokwiLoad.topic} ${JSON.stringify(wokwiLoad.payload)}`);
  return [telemetry, status, response, wokwiLoad];
} catch (error) {
  const response = { ...msg, statusCode: 400, payload: { error: error.message }, headers: { 'content-type': 'application/json; charset=utf-8' } };
  return [null, null, response, null];
}

const service = global.get('inventory');
const store = global.get('inventoryStore') || service.createInitialStore();
try {
  const result = service.updateOrderStatus(store, msg.req.params.orderId, msg.payload && msg.payload.status);
  global.set('inventoryStore', result.store);
  const state = { ...result.stateMessage, qos: 1, retain: true };
  const response = { ...msg, statusCode: 200, payload: result.order, headers: { 'content-type': 'application/json; charset=utf-8' } };
  return [state, response];
} catch (error) {
  const response = { ...msg, statusCode: error.message.startsWith('Unknown') ? 404 : 400, payload: { error: error.message }, headers: { 'content-type': 'application/json; charset=utf-8' } };
  return [null, response];
}
